var n=`0874-bhuna-khichuri`;var t=`world-0874`;var a=`BD`;var r=`south-asia`;var s=4;var g=169;var o={en:`Bhuna Khichuri`,ua:`Бгуна кхічурі`};var l={en:`Bhuna Khichuri is a Bangladesh dish made with red lentils, basmati rice, yellow onion, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Бгуна кхічурі, страва кухні країни Бангладеш. Основні складники: червона сочевиця, рис басматі, жовта цибуля, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Soak the listed rice, grains or noodles in clean water for about 120 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 120 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:120,i:[[`red-lentils`,220,`g`],[`basmati-rice`,330,`g`],[`water`,1e3,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,220,`g`],[`ghee`,55,`g`],[`ginger-garlic-paste`,22,`g`],[`ground-turmeric`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 34 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 34 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:34,i:[[`water`,900,`ml`],[`cauliflower`,170,`g`],[`frozen-green-peas`,110,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`serrano-pepper`,2,`pcs`],[`cilantro`,18,`g`]]}];var d={slug:n,id:t,country:`BD`,region:r,servings:4,minutes:169,title:o,text:l,steps:h};export{a as country,d as default,t as id,g as minutes,r as region,s as servings,n as slug,h as steps,l as text,o as title};